public class MembershipAudit { static boolean valid(String s){return s!=null&&s.length()==4&&s.charAt(0)=='R'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));} static String audit(Object[]a){int p=0,n=0,f=0,r=0;for(Object o:a){if(o==null){n++;continue;}p++;if(o.getClass().getSimpleName().contains("Faculty"))f++;else r++;}return p+" processed | "+n+" null skipped | "+f+" faculty | "+r+" regular";} public static void main(String[]x){System.out.println(valid("R12A"));}}
